{
  "concepts": [
    {
      "conditions": [],
      "definition": "Tests are proof projections from admitted work authority. Their expectation authority, interpreted predicate and derivation are distinct from execution provenance identifying the actual subject, checker, environment, observations and result.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1072,
          "quote": "Tests are proof projections from admitted work authority.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/TICKET_METHOD.md#Ticket%20Method%2FTicket%20Rules%2FTest%20Case%20Authority",
          "start_line": 1072
        }
      ],
      "key": "test_case_authority",
      "label": "Test case authority"
    },
    {
      "conditions": ["ticket_category: implementation_migration"],
      "definition": "A ticket category supplying concrete migration declarations, break/closure maps and review evidence to Spec's migration law. It is a ticket-local enforcement surface, not a competing migration policy.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1137,
          "quote": "This ticket family chooses the concrete\ndeclaration, break/closure map and review checklist; it supplies evidence to\nthat law, not another migration policy or permission to reinterpret it.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/TICKET_METHOD.md#Ticket%20Method%2FTicket%20Rules%2FImplementation%20Migration%20Category",
          "start_line": 1135
        }
      ],
      "key": "implementation_migration",
      "label": "Implementation migration"
    },
    {
      "conditions": [],
      "definition": "migration_strategy selects inside_out_hard_break or fundamental_re_adoption. The latter classifies inherited implementation as carry_across, redundant or rewrite.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1276,
          "quote": "Allowed inherited-implementation classifications are:\n\n- `carry_across`\n- `redundant`\n- `rewrite`\n\nUnclassified inherited implementation blocks closure.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/TICKET_METHOD.md#Ticket%20Method%2FTicket%20Rules%2FMigration%20Strategy%20Requirements",
          "start_line": 1270
        },
        {
          "end_line": 1196,
          "quote": "Allowed values are:\n\n- `inside_out_hard_break`\n- `fundamental_re_adoption`",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/TICKET_METHOD.md#Ticket%20Method%2FTicket%20Rules%2FImplementation%20Migration%20Category",
          "start_line": 1193
        }
      ],
      "key": "migration_strategy",
      "label": "Migration strategy"
    },
    {
      "conditions": ["Implementation migration ticket"],
      "definition": "library_usage records whether the active boundary rebuilds a pattern locally, consumes a reusable library/commonization surface, or extends that surface before local implementation lands. Its values are none, consume and extend.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1286,
          "quote": "Implementation migration tickets must declare whether the active boundary is:\n\n- rebuilding a pattern locally\n- consuming an existing reusable library/commonization surface\n- extending that surface before the local implementation lands\n\nThis is what `library_usage` records.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/TICKET_METHOD.md#Ticket%20Method%2FTicket%20Rules%2FRecurring%20Realization%20And%20Library%20Declaration",
          "start_line": 1280
        },
        {
          "end_line": 1202,
          "quote": "Allowed `library_usage` values are:\n\n- `none`\n- `consume`\n- `extend`",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/TICKET_METHOD.md#Ticket%20Method%2FTicket%20Rules%2FImplementation%20Migration%20Category",
          "start_line": 1198
        }
      ],
      "key": "library_usage",
      "label": "Library usage and recurrence"
    },
    {
      "conditions": ["The same work item is processed across multiple build tenants", "Review concerns backlog/active tickets"],
      "definition": "Tenant-local ticket lifecycles, proof surfaces, closure laws and follow-on work remain independently reviewable.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1321,
          "quote": "1. each tenant has its own suffixed ticket\n2. each ticket names its `build_tenant`\n3. each tenant ticket has its own proof surface and closure law\n4. one tenant's green proof does not stand in for another tenant's closure",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/TICKET_METHOD.md#Ticket%20Method%2FTicket%20Rules%2FMulti-Build-Tenant%20Review%20Rule",
          "start_line": 1318
        }
      ],
      "key": "tenant_ticket_review",
      "label": "Multi-build-tenant review"
    },
    {
      "conditions": [],
      "definition": "Ticket-specific functional review distinguishes source-truth migration from renaming, wrapping, adapting or relocating a surviving semantic center.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1329,
          "quote": "Implementation migration tickets must make the review problem concrete enough\nthat an implementor cannot land a rename, adapter, wrapper, or happy-path proof\nand claim source-truth migration.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/TICKET_METHOD.md#Ticket%20Method%2FTicket%20Rules%2FImplementation%20Migration%20Review%20Disambiguation",
          "start_line": 1327
        }
      ],
      "key": "functional_migration_review",
      "label": "Functional migration review"
    },
    {
      "conditions": ["Core-interface, carrier or authoritative-contract migration"],
      "definition": "A named walk of every live interface capable of bypassing, reinterpreting, replaying or projecting the migrating truth path, with an interface-specific closure criterion for each item.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1370,
          "quote": "This checklist is a named walk of every live interface that can still bypass,\nreinterpret, replay, or project the migrating truth path.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/TICKET_METHOD.md#Ticket%20Method%2FTicket%20Rules%2FImpacted%20Interface%20Review%20Checklist",
          "start_line": 1369
        }
      ],
      "key": "impacted_interface_checklist",
      "label": "Impacted Interface Review Checklist"
    },
    {
      "conditions": ["Implementation migration touches a core interface"],
      "definition": "Required Break Order is an ordered execution description proceeding outward from authoritative source truth. A Break-To-Closure Map identifies which break closes which closure-law clause when multiple old interfaces exist.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1427,
          "quote": "The ticket must also include a `Break-To-Closure Map` when the migration has\nmultiple old interfaces. The map must state which break closes which\nclosure-law clause. Without that map, partial landing can look like full\nlanding.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/TICKET_METHOD.md#Ticket%20Method%2FTicket%20Rules%2FRequired%20Break%20Order%20And%20Break-To-Closure%20Map",
          "start_line": 1424
        }
      ],
      "key": "break_to_closure",
      "label": "Required break order and break-to-closure map"
    },
    {
      "conditions": ["Migration ticket"],
      "definition": "Negative or structural proof addresses whether an old path can still satisfy the closure law; positive behavior proof alone is insufficient.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1447,
          "quote": "For a migration ticket, positive behavior proof is not enough.\n\nThe proof surface should include at least one negative or structural proof that\nthe old path can no longer satisfy the closure law.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/TICKET_METHOD.md#Ticket%20Method%2FTicket%20Rules%2FMixed-State%20Negative%20Proof",
          "start_line": 1444
        }
      ],
      "key": "mixed_state_negative_proof",
      "label": "Mixed-state negative proof"
    },
    {
      "conditions": [],
      "definition": "The minimum work-carrier states are backlog, active and completed. They are carrier states rather than a second result algebra; claims of valid transitions have their own exact predicates and core results.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1488,
          "quote": "These values select work-carrier state, not a second result algebra. A claim\nthat a state transition is valid carries its own core result and exact\npredicate.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/TICKET_METHOD.md#Ticket%20Method%2FTicket%20Rules%2FAllowed%20Status",
          "start_line": 1486
        }
      ],
      "key": "ticket_status",
      "label": "Ticket status"
    },
    {
      "conditions": [],
      "definition": "Product Definition Overlay bindings ticketing.tickets.lanes.backlog, .active and .completed locate tickets, defaulting respectively to .ai-workspace/tickets/backlog/, .ai-workspace/tickets/active/ and .ai-workspace/tickets/completed/. Backlog is accepted durable visible work outside current execution focus; active is the bounded execution set; completed is closed work retained as history. This arrangement keeps active search readable without placing deferred work in comments or goals.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1514,
          "quote": "- `backlog`: accepted durable work that should remain visible but is not part\n  of the current execution focus\n- `active`: the current bounded execution set\n- `completed`: closed work retained as history",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/TICKET_METHOD.md#Ticket%20Method%2FTicket%20Rules%2FTicket%20Lanes",
          "start_line": 1511
        },
        {
          "end_line": 1507,
          "quote": "Completed tickets move to `ticketing.tickets.lanes.completed`. The default is:\n\n- `.ai-workspace/tickets/completed/`",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/TICKET_METHOD.md#Ticket%20Method%2FTicket%20Rules%2FTicket%20Lanes",
          "start_line": 1505
        }
      ],
      "key": "ticket_lanes",
      "label": "Ticket lanes"
    },
    {
      "conditions": [],
      "definition": "UP-009 distinguishes owning work state from its views: Goals own the bounded work wave, tickets own ticket state, milestone authority owns subordinate milestone state, and accepted design owns realization decisions. Comments, dashboards, registers, indexes and generated summaries are projections.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1529,
          "quote": "Work-carrier state has one authority chain: Goals own the bounded work wave, the ticket\nowns ticket state, milestone authority owns subordinate milestone state, and\naccepted design owns realization decisions. Comments, dashboards, registers,\nindexes, and generated summaries are projections.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/TICKET_METHOD.md#Ticket%20Method%2FTicket%20Rules%2FOne-Truth%20State%20Projection%20And%20Drift%20Refusal%20%28%60STDO-UP-009%60%29",
          "start_line": 1526
        }
      ],
      "key": "work_state_projection",
      "label": "One-truth work-state projection"
    },
    {
      "conditions": ["Illustrative recommended document shape"],
      "definition": "The sprint example SPRINT-2026-04-30-operational-projection is active, goal operational-projection-ux, opened and updated 2026-04-30T09:00:00Z. It cites GOALS, PRODUCT and a governing design surface. Its scope is operational projection layout, readability, interaction affordance and visual evidence; it excludes Product truth, data-contract, runtime/governance changes and new constructive carriers. It expects realization_refactor. UXI-001 improves relation-line readability, cites screenshots/2026-04-30/UXI-001.png and carries pending accessibility contrast debt. Closure triggers are timebox, changed surface volume or design-lead request; closure law is a forensic authority walkthrough of each changed state; proof is screenshots and walkthrough notes. Deferred compliance includes screenshots, accessibility and event replay; hidden Product/data-contract drift prevents closure; accepted local debt receives paydown tickets and authority drift is repriced.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1588,
          "quote": "- closure_trigger: timebox, changed surface volume, or design-lead close request\n- closure_law: forensic walkthrough reviews each changed state against authority\n- proof_surface: screenshots plus walkthrough notes\n- deferred_compliance: screenshots, accessibility check, event-replay review\n- non_closure_conditions: product truth or data contract drift remains hidden\n- paydown_policy: open paydown tickets for accepted local debt; reprice authority drift",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/TICKET_METHOD.md#Ticket%20Method%2FRecommended%20Ticket%20Shape",
          "start_line": 1583
        }
      ],
      "key": "recommended_sprint_example",
      "label": "Recommended sprint example"
    },
    {
      "conditions": ["Illustrative recommended document shape"],
      "definition": "T-001, Add Product Layer To SPEC_METHOD, illustrates an active high-priority ordinary feature under methodology-bootstrap, change_class product_reprice, re_entry_point product, and triage/create/update date 2026-04-07. Its intent is an explicit Product-definition layer in the constitutional chain. Its context says SPEC_METHOD omitted that layer; acceptance asks for PRODUCT.md in the chain, intent -> product -> requirements in bootstrap, and corresponding examples/reconstruction logic. Its comment link is a placeholder, not evidence of a performed change.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1616,
          "quote": "- `PRODUCT.md` is part of the constitutional chain\n- bootstrap sequence includes `intent -> product -> requirements`\n- examples and reconstruction logic reflect the new layer",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/TICKET_METHOD.md#Ticket%20Method%2FRecommended%20Ticket%20Shape",
          "start_line": 1614
        }
      ],
      "key": "recommended_ordinary_ticket_example",
      "label": "Recommended ordinary ticket example"
    },
    {
      "conditions": ["Illustrative implementation-migration ticket"],
      "definition": "B-010 illustrates an active bug replacing mixed gap projection with one authoritative declared carrier: inside_out_hard_break, library_usage none with a boundary-specific/non-recurring rationale, goal operator-gap-truth, design_reframe, design_surface re-entry, triage/create/update 2026-04-20. Affected scope is the operator-query acceptance path; excluded/disjoint scopes are explicitly absent. Old truth is fallback gap projection with synthetic convergence fields; new truth is declared-obligation projection with separately classified fallback gaps. Old producer is <gap-module>::build_fallback_gap; new producers are <obligation-module>::collect_declared_obligations and <gap-module>::build_canonical_gap. Both consumer lists name <query-module>::project_gaps, <summary-module>::project_span and <review-surface>::render. Derived surfaces are <query-surface>::gaps, <summary-surface>::span and <proof-surface>::first_slice_negative. Closure requires old projection no longer authoritative in scope and rejects mixed old/new proof as acceptance. All checklist boxes are initially unchecked, including scope/routing or explicit absence, old/new paths, producers/consumers/projections, demotion/removal, mixed-state refusal, test repricing, recurrence/library review, tenant isolation and reconciliation of wording/proof.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1657,
          "quote": "- closure_law: migration closes only when the old projection is no longer authoritative within the affected scope and mixed old/new proof does not count as acceptance",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/TICKET_METHOD.md#Ticket%20Method%2FRecommended%20Ticket%20Shape",
          "start_line": 1657
        }
      ],
      "key": "recommended_migration_ticket_example",
      "label": "Recommended migration ticket example"
    },
    {
      "conditions": ["Default local-file carrier selected"],
      "definition": "The operating mode assumes humans and agents directly read the active folder; backlog remains durable/searchable without competing for immediate attention; rg suffices for active-work discovery; no database or board is required. The three shell examples describe header/status/type/goal searches in active and backlog folders and T-001/B-002 searches across tickets.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1687,
          "quote": "- humans and agents can read the active ticket folder directly\n- backlog remains searchable durable work, but does not compete with the active\n  lane for immediate attention\n- `rg` is sufficient for finding active work\n- no database or board is required",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/TICKET_METHOD.md#Ticket%20Method%2FOperating%20Mode",
          "start_line": 1683
        }
      ],
      "key": "local_file_operating_mode",
      "label": "Local-file operating mode"
    },
    {
      "conditions": [],
      "definition": "GOALS answers which broad work wave matters; SPEC_METHOD supplies constitutional change class/re-entry; sprints identify the bounded execution batch pricing proof, evidence and paydown; tickets identify durable work and state; comments record proposals, arguments, decisions, reviews and handoffs; POSTING_GUIDE structures/names comment publications. The separation prevents goals becoming backlog, deferred work diluting active focus, comments becoming informal status and task boards becoming accidental authority.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1709,
          "quote": "- `GOALS.md` answers: what broad work wave matters now\n- `SPEC_METHOD.md` answers: what constitutional change class and re-entry point\n  govern the work\n- sprints answer: what bounded execution batch is currently pricing proof,\n  evidence, and paydown\n- tickets answer: what durable units of work exist and what state they are in\n- comments answer: what was proposed, argued, decided, reviewed, or handed off\n- `POSTING_GUIDE.md` answers: how comment-layer publications are structured and\n  named",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/TICKET_METHOD.md#Ticket%20Method%2FRelationship%20To%20Other%20Surfaces",
          "start_line": 1701
        }
      ],
      "key": "work_surface_roles",
      "label": "Work-surface roles"
    },
    {
      "conditions": [],
      "definition": "Possible future extensions are generated active boards, dependency checks, scenario/requirement/ADR links, external ticket-system sync and message-board integration via a standard tool-protocol capability.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1728,
          "quote": "This minimal method can later grow into:\n\n- a generated active board\n- ticket dependency checks\n- links from tickets to scenario, requirement, or ADR surfaces\n- external sync with a real ticketing system\n- message-board integration through a standard tool-protocol capability",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/TICKET_METHOD.md#Ticket%20Method%2FFuture%20Extensions",
          "start_line": 1722
        }
      ],
      "key": "ticket_carrier_extensions",
      "label": "Ticket carrier extensions"
    },
    {
      "conditions": ["Selected foundational premises and instance choices"],
      "definition": "The Transformation Library owns shared contracts for purposeful specification-governed construction in urn:stdo:bounded-context:transformation-library, under the STDO Specification Methodology Product authority. Its basis is the exact member digest and source-owned contracts under the activation's governing cut. Bind, Acquire, Transform, Evaluate, Conjoin and Dispose are composable/co-locatable responsibilities, not compulsory stages, actors or runtime APIs. Methods bind concrete types, predicates, refinements, applicability, adoption and grants without making competing determinations.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 14,
          "quote": "The contracts below decide recurring application, projection and composition\nquestions. They are conditional on the selected foundational premises and\ninstance choices. Particular methods bind concrete types, predicates, result\nrefinements, applicability, adoption and grants. Those bindings apply the\nshared law; they do not restate it as a competing determination. A contract\ndefinition grants no operation or decision authority.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/TRANSFORMATION_LIBRARY.md#Transformation%20Library",
          "start_line": 9
        }
      ],
      "key": "transformation_library",
      "label": "Transformation Library"
    },
    {
      "conditions": [],
      "definition": "Unchanged owner-qualified references from urn:stdo:bounded-context:reference-frame-evaluation distinguish frame-set authority (human declares/accepts project frame set), semantic authority (meaning owner), evaluation authority (permitted evaluator), operation authority (owner-issued construction/transformation/admission/publication/mutation grant), decision authority (permitted result disposer) and actor identity (human, agent, tool or process doing work). Import direction is source to library with no translation, loss, inverse or ownership transfer.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 34,
          "quote": "Direction is source to this contract account; meanings are unchanged owner-qualified\nreferences, with no translation, loss, inverse or ownership transfer. The source\ncontext and owner are declared in [Frame Method's Position](REFERENCE_FRAME_METHOD.md#position).",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/TRANSFORMATION_LIBRARY.md#Transformation%20Library%2FReference-only%20semantic%20imports",
          "start_line": 32
        }
      ],
      "key": "reference_authority_vocabulary",
      "label": "Reference-only authority vocabulary"
    },
    {
      "conditions": ["One selected operation under the selected complete STDO basis"],
      "definition": "The foundational contract parameterizes input/output domains X/Y, interpretation K, outcome predicate P, material identity/state relations I and actual effect/decision grant G. These are semantic parameters rather than serialized fields or a universal schema. Original domain outcomes and their total refinement into the core result algebra remain instance-owned; unknown judgment, non-performance and uncertain effects remain separate.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 75,
          "quote": "For one selected operation, let X and Y be its declared input and output\ndomains, K its interpretation, P its required outcome predicate, I its material\nidentity/state relations and G its actual effect or decision grant. These are\nparameters, not serialized fields or a universal schema. The instance owns its original domain outcomes and their total refinement into\n[the core result algebra](FOUNDATIONS.md#result-algebra). Unknown judgment,\nnon-performance and uncertain effects retain their separate coordinates.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/TRANSFORMATION_LIBRARY.md#Transformation%20Library%2FFoundational%20contract",
          "start_line": 70
        }
      ],
      "key": "foundational_operation_contract",
      "label": "Foundational operation contract"
    },
    {
      "conditions": [],
      "definition": "Contract application determines whether a proposed operation or reliance is admissible under a bound contract, separately from whether it achieves its outcome. Input/output domains, predicate, governing constraints, material relations, evidence rule, grants, owners and current basis are semantic coordinates supportable by existing design, frame, function or work carriers, without a mandated record format or additional validation stage.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 127,
          "quote": "The application predicate is: **this proposed operation or reliance is\nadmissible under this bound contract**. It differs from the predicate that the\noperation achieves its intended outcome. Application uses the following\nconditions once at the responsible consumer:",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/TRANSFORMATION_LIBRARY.md#Transformation%20Library%2FContract%20application",
          "start_line": 124
        }
      ],
      "key": "contract_application",
      "label": "Contract application"
    },
    {
      "conditions": ["Current subject and basis"],
      "definition": "The constraint surface describes work allowed by bound constraints/grants, unresolved obligations and choices reserved to an owner. Established facts, assumptions, discretion and unknowns are distinct; acquiring the abstract surface alone is not a complete activation without the actual material subject.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 194,
          "quote": "For a current subject and basis, the bound contract describes the work allowed\nby its constraints and grants. It also exposes obligations still unresolved.\nThis is the task's constraint surface. It distinguishes the permitted choices\ninside the contract from the choices reserved to an owner. A missing condition\nis not freedom; a condition proved irrelevant to this task need not be loaded\nagain while that proof remains applicable.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/TRANSFORMATION_LIBRARY.md#Transformation%20Library%2FContract%20application%2FConstraint%20surface",
          "start_line": 189
        }
      ],
      "key": "constraint_surface",
      "label": "Constraint surface"
    },
    {
      "conditions": ["Declared source-to-consumer relation"],
      "definition": "Faithful projection applies Contract application with authoritative source/selector, target interpretation, consumer task, required distinctions, admitted loss/approximation and invalidation conditions. Source and target retain separate identities; publication/adoption conditions remain domain-owned.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 217,
          "quote": "A projection or interpretation applies Contract application to a declared\nsource-to-consumer relation. Its binding states the authoritative source and\nselector, target interpretation, consumer task, required distinctions, admitted\nloss or approximation, and invalidation conditions. Source and target retain\ntheir own identities. The domain owns additional publication and adoption\nconditions.",
